### Instruction:
Create a C++ program that sorts a given array in descending order.

### Input:
int array[] = {6, 3, 8, 12, 9, 4};

### Response:
#include<iostream>
using namespace std;

int main()
{
    int array[] = {6, 3, 8, 12, 9, 4};
    int arraySize = sizeof(array)/sizeof(array[0]);

    //ascending order sorting
    for(int i = 0; i < arraySize; i++)
    {
        // find the position of smallest element
        int small = i;
        for(int j = i+1; j < arraySize; j++)
        {
            if(array[j] > array[small])
                small = j;
        }

        // swap the position of smallest element
        int temp = array[i];
        array[i] = array[small];
        array[small] = temp;
    }

    // print the sorted array
    cout << "Sorted array : ";
    for(int i = 0; i < arraySize; i++)
        cout << array[i] << " ";

    return 0;
}

### Instruction:
Write a C program to find the sum of all digits of a given number

### Response:
#include <stdio.h>

int getSumOfDigits(int num) {
    // Initialize sum
    int sum = 0;

    // Find the sum of digits
    while(num > 0) {
        sum += num % 10;
        num /= 10;
    }

    return sum;
}

int main() {
    int num;
    scanf("%d", &num);

    printf("Sum of digits of %d is %d\n", num, getSumOfDigits(num));

    return 0;
}

