### Input:
array = [10, 15, 7, 2, 13, 18]

### Response:
public static void sortDesc(int[] array) {
    for(int i = 0; i < array.length; i++) {
        for(int j = 1; j < array.length; j++) {
            if(array[j-1] < array[j]) {
                int temp = array[j-1];
                array[j-1] = array[j];
                array[j] = temp;
            }
        }
    }
}

