    if(str1.length() != str2.length()){
        return false;
    }
    char[] char1 = str1.toCharArray();
    char[] char2 = str2.toCharArray();
    Arrays.sort(char1);
    Arrays.sort(char2);
    return Arrays.equals(char1, char2);
}

