public double getMedian(int[] arr) { 
    Arrays.sort(arr); 

    int len = arr.length; 
    double median = 0; 

    if (len % 2 == 0) { 
        int a = arr[len / 2]; 
        int b = arr[(len / 2) - 1]; 
        median = (a + b) / 2.0; 
    } 

    else { 
        median = arr[len / 2]; 
    } 

    return median; 
}

