function sendPushNotification() {
  const message = "This is a reminder that your deadline is approaching"; 
  const notification = new Notifications({message})
  notification.send();
};

// Function to monitor the deadline
function deadlineMonitor() {
  setInterval(function(){
    // Call function to check if the deadline has been reached
    deadlineReached();
  }, 5000);
}

// Function to check if the deadline has been reached
function deadlineReached() {
  // Set deadline
  let deadline = new Date();
  deadline.setMinutes(deadline.getMinutes() + 15);

  // Current date
  const date = new Date();

  // If the current date is equal to the deadline, call the push notification
  if (date === deadline) {
    sendPushNotification();
  }
}

