function getFirstFiftyPrimes(){
  let primes = [2];
  let num = 3;

  while(primes.length < 50){
      let isPrime = true;
      for(let i = 0; i < primes.length; i++){
          if(num % primes[i] === 0){
              isPrime = false;
          }
      }
      if(isPrime)
        primes.push(num);
      num += 1;
  }

  return primes;
}

