// A utility function to calculate the discriminant 
float discriminant(float a, float b, float c) 
{ 
    return (b*b - 4*a*c); 
} 

// Function to calculate the roots of Quadratic Equations 
void findRoots(float a, float b, float c) 
{ 
    float discriminant = discriminant(a, b, c); 

    if (discriminant > 0) 
    { 
        float x1 = (-b + sqrt(discriminant)) / (2*a); 
        float x2 = (-b - sqrt(discriminant)) / (2*a); 
        printf("Roots are real and distinct.\nx1 = %f, x2 = %f", x1, x2); 
    } 
    else if (discriminant == 0) 
    { 
        float x = -b / (2*a); 
        printf("Roots are real and same.\nx1 = x2 = %f", x); 
    } 
    else
    { 
        printf("Roots are complex.\n"); 
    } 
} 

