### Instruction:
Given an array of integers, write an algorithm to sort them in an ascending order.

### Input:
arr = [23, 32, 19, 17, -5, 3]

### Response:
let arrLength = arr.length;
let temp;

for(i = 0; i < arrLength; i++){
   for(j = 0; j < (arrLength - i - 1); j++){
	   // Compare two adjacent elements
       if(arr[j] > arr[j+1]){
          // Swap them
          temp = arr[j];
          arr[j] = arr[j+1];
          arr[j+1] = temp;
       }
    }
}

