### Input:
12 and 18

### Response:
public static int getSmallestCommonDenominator(int a, int b){
    int gcd = 1;          
    int smallNumber = Math.min(a, b);

     for(int i = 1; i <= smallNumber; i++) 
    {
        if(a % i == 0 && b % i == 0) 
            gcd = i;
    } 
    int lcm = (a*b)/gcd; 

    return lcm; 
}

