public static int calculateCombinations(List<String> items){
            int totalCombinations = 0;

            for(int i = 0; i < Math.pow(2, items.size()); i++){
                int count = 0;
                String combination = "";
                for(int j = 0; j < items.size(); j++){
                    if( (i & (1 << j)) > 0){
                        count++;
                        combination += items.get(j) + " ";
                    }
