### Instruction:
Build a state machine to simulate a vending machine.

### Response:
// States
const IDLE = 'IDLE';
const COIN_INPUT = 'COIN_INPUT';
const SELECTION = 'SELECTION';
const DISPENSE = 'DISPENSE';

// Transitions
const transitions = {
    [IDLE]: [COIN_INPUT],
    [COIN_INPUT]: [SELECTION],
    [SELECTION]: [DISPENSE],
    [DISPENSE]: [IDLE]
};

// Actions
const ENTER_COIN = 'enter_coin';
const SELECT_ITEM = 'select_item'; 
const DISPENSE_ITEM = 'dispense_item';

// State machine
const stateMachine = createStateMachine({
    transitions: transitions,
    actions: {
        [ENTER_COIN]: (args) => enterCoin(args),
        [SELECT_ITEM]: (args) => selectItem(args),
        [DISPENSE_ITEM]: (args) => dispenseItem(args)
    }
});

// Vending machine
const vendingMachine = {
    // Initial state
    currentState: IDLE,

    // Methods
    enterCoin: (args) => stateMachine.invoke(ENTER_COIN, args),
    selectItem: (args) => stateMachine.invoke(SELECT_ITEM, args),
    dispenseItem: (args) => stateMachine.invoke(DISPENSE_ITEM, args)
};

### Instruction:
Write a Java method to convert a given integer to its equivalent English words

### Response:
public static String intToEnglish(int input) {

        // create an array of string representations of numbers 1 to 19  
        String[] numbers1_19 = {"one", "two", "three", "four", "five", "six",  
                "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",  
                "fourteen", "fifteen", "sixteen", "seventeen", "eighteen",  
                "nineteen"};  

        // create an array of string representations of multiples of ten  
        // from 20 to 90  
        String[] multiplesOfTen = {" twenty", " thirty", " forty",  
                " fifty", " sixty", " seventy", " eighty", " ninety"};  

        String output = "";  

        // extract each digit from the input and convert it to its  
        // string representation  
        if (input > 0 && input < 20) {  
            output += numbers1_19[input - 1] + " ";  
        } else if (input >= 20 && input < 100) {  
            output += multiplesOfTen[input / 10 - 2] + " ";  
            if (input % 10 != 0) {  
                output += intToEnglish(input % 10);  
            }  
        } else if (input >= 100 && input < 1000) {  
            output += intToEnglish(input / 100) + " hundred ";  
            if (input % 100 != 0) {  
                output += intToEnglish(input % 100);  
            }  
        }  
        // return the output string  
        return output;
    }

